def prose(s):
 # Keep identifiers, URLs and code literal. Normalize generated engineering prose.
 protected={}
 def stash(m):
  key='@@PROTECTED'+str(len(protected))+'@@';protected[key]=m.group();return key
 s=re.sub(r'`[^`]+`|https?://[^\s)]+',stash,s)
 s=re.sub(r'([,;:])(?=[A-Za-z])',r'\1 ',s)
 s=re.sub(r'(\d)(mm[²³]?|µm|K/W|°C|EUR|W)(?=\b|[a-z])',r'\1 \2',s)
 s=re.sub(r'(\d (?:mm[²³]?|µm|K/W|°C|EUR|W))(?=[A-Za-z])',r'\1 ',s)
 for a,z in {'sourcevias':'source vias','thermalvias':'thermal vias','jointvias':'joint vias','sourcejoint':'source joint','sourcepad':'source pad','sourceopening':'source opening','sourcewing':'source wing','sourceassembly':'source assembly','PCBsize':'PCB size','RFvalues':'RF values','RFparasitics':'RF parasitics','RFoperation':'RF operation','RFAM':'RF AM','barflatness':'bar flatness','barrelplating':'barrel plating','controllercontract':'controller contract','CADbaseline':'CAD baseline','enduranceacceptance':'endurance acceptance','courtyardwarnings':'courtyard warnings','manufacturer maps':'manufacturer maps','source/RF/mechanical/modelnegative':'source/RF/mechanical/model negative','standardDFMmutations':'standard DFM mutations','baseline mutations':'baseline mutations','GateA':'Gate A','GateB':'Gate B','GateC':'Gate C','GateD':'Gate D','GateE':'Gate E','PAassembly':'PA assembly','prototype processDEFINED':'prototype process DEFINED','checksPASS':'checks PASS','remainsOPEN':'remains OPEN','for5before':'for 5 before','at1/':'at 1 /','at10':'at 10','at1':'at 1','priceguarantee':'price guarantee','reworkunquoted':'rework unquoted','before4':'before 4','and20':'and 20','Eleven standardDFM':'Eleven standard DFM','KiCad10':'KiCad 10','110°Ctarget':'110°C target','125°Cgate':'125°C gate','conservative110':'conservative 110','nominal18':'nominal 18','conservative10':'conservative 10','contact10':'contact 10','sameE':'same E','originalHOLD':'original HOLD','preserved at920':'preserved at 920','andGate':'and Gate','Nooperation':'No operation'}.items():s=s.replace(a,z)
 s=re.sub(r'(?<=\d)(?=(?:open|side|end|wing|logic|states|baseline|manufacturer|STpositions|package-padsets|individually|errors|warnings|unrouted|parity|exclusions|source|networks)\b)', ' ',s)
 s=re.sub(r'\)(?=[A-Za-z])',') ',s)
 for key,value in protected.items():s=s.replace(key,value)
 return s
def write(path,s):path.write_text((prose(s)if path.suffix=='.md'else s).strip()+'\n')
